TLM.f("Sancti/11-17",{"officium":"S. Gregorii Thaumaturgi Episcopi et Confessoris","rule":["Evangelium non appropriatum","vide C4;","Gloria"],"fallback":"Commune/C4","from":{"Introitus":"Commune/C4","Lectio":"Commune/C4","Graduale":"Commune/C4","GradualeP":"Commune/C4","Tractus":"Commune/C4","Offertorium":"Commune/C4","Secreta":"Commune/C4","Communio":"Commune/C4"},"sections":{"Introitus":[{"k":"ref","la":"Eccli 45:30"},{"k":"text","la":"Státuit ei Dóminus testaméntum pacis, et príncipem fecit eum: ut sit illi sacerdótii dígnitas in ætérnum. (Allelúja, allelúja.)"},{"k":"ref","la":"Ps 131:1"},{"k":"text","la":"Meménto, Dómine, David: et omnis mansuetúdinis ejus."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Státuit ei Dóminus testaméntum pacis, et príncipem fecit eum: ut sit illi sacerdótii dígnitas in ætérnum. (Allelúja, allelúja.)"}],"Oratio":[{"k":"text","la":"Da, quǽsumus omnípotens Deus: ut beáti Gregórii Confessóris tui atque Pontíficis veneránda solémnitas, et devotiónem nobis áugeat et salútem."},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Léctio libri Sapiéntiæ"},{"k":"ref","la":"Eccli 44:16-27; 45, 3-20"},{"k":"text","la":"Ecce sacérdos magnus, qui in diébus suis plácuit Deo, et invéntus est justus: et in témpore iracúndiæ factus est reconciliátio. Non est invéntus símilis illi, qui conservávit legem Excélsi. Ideo jurejurándo fecit illum Dóminus créscere in plebem suam. Benedictiónem ómnium géntium dedit illi, et testaméntum suum confirmávit super caput ejus. Agnóvit eum in benedictiónibus suis: conservávit illi misericórdiam suam: et invénit grátiam coram óculis Dómini. Magnificávit eum in conspéctu regum: et dedit illi corónam glóriæ. Státuit illi testaméntum ætérnum, et dedit illi sacerdótium magnum: et beatificávit illum in glória. Fungi sacerdótio, et habére laudem in nómine ipsíus, et offérre illi incénsum dignum in odórem suavitátis."}],"Graduale":[{"k":"ref","la":"Eccli 44:16"},{"k":"text","la":"Ecce sacérdos magnus, qui in diébus suis plácuit Deo."},{"k":"ref","la":"Eccli 44:20"},{"k":"text","la":"Non est invéntus símilis illi, qui conserváret legem Excélsi. Allelúja, allelúja."},{"k":"ref","la":"Ps 109:4"},{"k":"text","la":"Tu es sacérdos in ætérnum, secúndum órdinem Melchísedech. Allelúja."}],"GradualeP":[{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Ps 109:4"},{"k":"text","la":"Tu es sacérdos in ætérnum, secúndum órdinem Melchísedech. Allelúja."},{"k":"text","la":"Hic est sacérdos, quem coronávit Dóminus. Allelúja.","mark":"V"}],"Tractus":[{"k":"ref","la":"Eccli 44:16"},{"k":"text","la":"Ecce sacérdos magnus, qui in diébus suis plácuit Deo."},{"k":"ref","la":"Eccli 44:20"},{"k":"text","la":"Non est invéntus símilis illi, qui conserváret legem Excélsi."},{"k":"ref","la":"Ps 111:1-3"},{"k":"text","la":"Beátus vir, qui timet Dóminum: in mandátis ejus cupit nimis."},{"k":"text","la":"Potens in terra erit semen ejus: generátio rectórum benedicétur.","mark":"V"},{"k":"text","la":"Glória et divítiæ in domo ejus: et justítia ejus manet in sǽculum sǽculi.","mark":"V"}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Marcum"},{"k":"ref","la":"Marc 11:22-24"},{"k":"text","la":"In illo témpore: Respóndens Jesus discípulis suis, ait illis: Habéte fidem Dei. Amen, dico vobis, quia, quicúmque díxerit huic monti: Tóllere et míttere in mare, et non hæsitáverit in corde suo, sed credíderit, quia, quodcúmque díxerit, fiat, fiet ei. Proptérea dico vobis: Omnia quæcúmque orántes pétitis, crédite quia accipiétis, et evénient vobis."}],"Offertorium":[{"k":"ref","la":"Ps 88:21-22"},{"k":"text","la":"Invéni David servum meum, óleo sancto meo unxi eum: manus enim mea auxiliábitur ei, et bráchium meum confortábit eum. (Allelúja.)"}],"Secreta":[{"k":"text","la":"Sancti tui, quǽsumus, Dómine, nos ubíque lætíficant: ut, dum eórum mérita recólimus, patrocínia sentiámus."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Luc 12:42"},{"k":"text","la":"Fidélis servus et prudens, quem constítuit dóminus super famíliam suam: ut det illis in témpore trítici mensúram. (Allelúja.)"}],"Postcommunio":[{"k":"text","la":"Praesta, quaésumus, omnípotens Deus: ut, de percéptis munéribus grátias exhibéntes, intercedénte beáto Gregório Confessóre tuo atque Pontífice, benefícia potióra sumámus."},{"k":"macro","name":"Per Dominum"}]},"hr":{"c02c414c737dacfd":{"t":"Sir 45, 30, Ps 131, 1\n(Sir 45, 30) Sklopio je Gospodin s njime savez mira učinio ga knezom da zauvijek bude u svećeničkom dostojanstvu. (Ps 131, 1) Spomeni se, Gospodine, Davida i sve njegove krotkosti.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Sir 45, 30) Sklopio je Gospodin s njime savez mira učinio ga knezom da zauvijek bude u svećeničkom dostojanstvu."},"001c48131282ee8c":{"t":"<i>Pomolimo se</i>.\nDaj, molimo, svemogući Bože, da nam časna svetkovina blaženoga Grgura, tvoga priznavaoca i biskupa uveća pobožnost i spasenje.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"95ddbdede28f22c8":{"t":"Sir 44, 16-27; 45, 3-20\nČitanje knjige Mudrosti. Evo velikog svećenika,koji se za svoga života svidio Bogu i bio je pravedan, te je postao pomirnikom u vrijeme srdžbe. Nitko se ne nađe tko bi kao on izvršavao zakon Svevišnjega. I jer mu se Gospodin zavjeri, učini da uzraste kao njegov narod. Izlio je na njega blagoslov svih naroda i nad njim je potvrdio svoj zavjet. Odlikovao ga je svojim blagoslovima, očuvao mu svoje milosrđe te je stekao milost pred Gospodinom. Proslavio ga je pred kraljevima i udijelio mu vijenac slave. Sklopio je s njim vječni zavjet i predao mu veliko svećenstvo. Usrećio ga je slavom da vrši svećeničku službu i blagoslivlja u njegovo ime i prinosi mu dostojan miomirisni kad."},"16468be514c64800":{"t":"Sir 44, 16, Sir 44, 20\n(Sir 44, 16) Evo velikog svećenika koje se za svoga života svidio Bogu. (Sir 44, 20) Nitko mu nije bio ravan u izvršavanju zakona Svevišnjega.\n\nPs 109, 4\n<i>Aleluja</i>, <i>aleluja</i>.\nTi si svećenik dovijeka po redu Melkisedekovu. <i>Aleluja</i>."},"8716687e2ee1bad1":{"t":"Mk 11, 22–24\nSlijedi sveto Evanđelje po Marku. U ono vrijeme reče Isus svojim učenicima: Imajte vjeru u Boga. Zaista vam kažem, ako tko reče ovoj gori: Digni se i baci se u more, i ne posumnja u svojem srcu nego uzvjeruje da će se dogoditi što govori, ispunit će mu se. Zaista vam kažem: Što god tražite u molitvi vjerujte da ćete primiti i ispunit će vam se."},"c1545941e0b9c017":{"t":"Ps 88, 21-22\nNašao sam Davida, slugu svojega, pomazao sam ga svojim svetim uljem. S njim će biti ruka moja i krijepit će ga desnica moja."},"3171212e73cd052d":{"t":"Neka nas, molimo, Gospodine, tvoji sveti posvuda razveseljuju, da osjetimo njihovu zaštitu dok štujemo njihove zasluge.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"404159d2e4df1ef4":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo tebi, Gospodine, sveti Oče, svemogući vječni Bože, po Kristu Gospodinu našemu. – Po njemu tvoje veličanstvo hvale anđeli, klanjaju se gospodstva i dršću vlasti. Nebesa i nebeske sile i blaženi serafini zajedničkim klicanjem slave. Daj, molimo, s njima i naše glase primi dok govorimo poniznim hvalospjevom:"},"43352d99b4b928c1":{"t":"Lk 12, 42\nEvo vjernog i razboritog sluge koga je postavio Gospodin nad svojom obitelji, da im na vrijeme daje za hranu pšenicu koja im pripada."},"f30805349508d1f0":{"t":"<i>Pomolimo se</i>.\nPodaj, molimo, svemogući Bože, da, dok ti na primljenim darovima zahvaljujemo, zagovorom tvoga blaženoga priznavaoca i biskupa Grgura još u obilnijoj mjeri primimo tvoja dobročinstva.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."}},"variants":{"paschal":{"Graduale":[{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Ps 109:4"},{"k":"text","la":"Tu es sacérdos in ætérnum, secúndum órdinem Melchísedech. Allelúja."},{"k":"text","la":"Hic est sacérdos, quem coronávit Dóminus. Allelúja.","mark":"V"}]}}});
